// Changes: Project and snapshot persistence (CRUD, optimistic revision check on save, automatic backups).

import { randomBytes } from 'node:crypto'
import { parseGrammar } from '#/lib/grammar'
import { normalizeProjectData, type ProjectData } from '#/lib/project'
import { getDb, transaction } from './db.server'

const AUTO_SNAPSHOT_EVERY_MS = 20 * 60 * 1000
const AUTO_SNAPSHOTS_KEPT = 30

export interface ProjectRecord {
  id: string
  name: string
  data: ProjectData
  revision: number
  createdAt: string
  updatedAt: string
}

export interface ProjectSummary {
  id: string
  name: string
  revision: number
  createdAt: string
  updatedAt: string
  llRules: number
  precSize: number
  snapshots: number
}

export interface SnapshotSummary {
  id: number
  label: string
  auto: boolean
  createdAt: string
}

export type SaveResult =
  | { status: 'saved'; revision: number; updatedAt: string }
  | { status: 'conflict'; project: ProjectRecord }
  | { status: 'missing' }

interface ProjectRow {
  id: string
  name: string
  data: string
  revision: number
  created_at: string
  updated_at: string
}

const now = () => new Date().toISOString()
const newId = () => randomBytes(8).toString('base64url')

const toRecord = (row: ProjectRow): ProjectRecord => ({
  id: row.id,
  name: row.name,
  data: normalizeProjectData(JSON.parse(row.data)),
  revision: row.revision,
  createdAt: row.created_at,
  updatedAt: row.updated_at,
})

const findRow = (id: string) => getDb().prepare('SELECT * FROM projects WHERE id = ?').get(id) as ProjectRow | undefined

export function listProjects(): ProjectSummary[] {
  const rows = getDb()
    .prepare(
      `SELECT p.*, (SELECT COUNT(*) FROM snapshots s WHERE s.project_id = p.id) AS snapshot_count
       FROM projects p ORDER BY p.updated_at DESC`,
    )
    .all() as unknown as (ProjectRow & { snapshot_count: number })[]
  return rows.map((row) => {
    const data = normalizeProjectData(JSON.parse(row.data))
    return {
      id: row.id,
      name: row.name,
      revision: row.revision,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      llRules: parseGrammar(data.ll.grammar).rules.length,
      precSize: data.prec.terminals.length ? data.prec.terminals.length + 1 : 0,
      snapshots: row.snapshot_count,
    }
  })
}

export function getProject(id: string): ProjectRecord | null {
  const row = findRow(id)
  return row ? toRecord(row) : null
}

export function createProject(name: string, data: ProjectData): ProjectRecord {
  const id = newId()
  const ts = now()
  getDb()
    .prepare('INSERT INTO projects (id, name, data, revision, created_at, updated_at) VALUES (?, ?, ?, 1, ?, ?)')
    .run(id, name, JSON.stringify(data), ts, ts)
  return getProject(id)!
}

function insertSnapshot(projectId: string, label: string, data: string, auto: boolean) {
  const db = getDb()
  const info = db
    .prepare('INSERT INTO snapshots (project_id, label, auto, data, created_at) VALUES (?, ?, ?, ?, ?)')
    .run(projectId, label, auto ? 1 : 0, data, now())
  if (auto) {
    db.prepare(
      `DELETE FROM snapshots WHERE project_id = ? AND auto = 1 AND id NOT IN
         (SELECT id FROM snapshots WHERE project_id = ? AND auto = 1 ORDER BY id DESC LIMIT ?)`,
    ).run(projectId, projectId, AUTO_SNAPSHOTS_KEPT)
  }
  return Number(info.lastInsertRowid)
}

export function saveProject(id: string, data: ProjectData, baseRevision: number): SaveResult {
  return transaction((db) => {
    const row = findRow(id)
    if (!row) return { status: 'missing' }
    if (row.revision !== baseRevision) return { status: 'conflict', project: toRecord(row) }
    const json = JSON.stringify(data)
    if (json === row.data) return { status: 'saved', revision: row.revision, updatedAt: row.updated_at }

    const lastAuto = db
      .prepare('SELECT created_at FROM snapshots WHERE project_id = ? AND auto = 1 ORDER BY id DESC LIMIT 1')
      .get(id) as { created_at: string } | undefined
    if (!lastAuto || Date.now() - Date.parse(lastAuto.created_at) > AUTO_SNAPSHOT_EVERY_MS) {
      insertSnapshot(id, 'Automatická záloha', row.data, true)
    }

    const ts = now()
    db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(json, ts, id)
    return { status: 'saved', revision: row.revision + 1, updatedAt: ts }
  })
}

// Overwrites the project with new data, keeping the previous state as a snapshot.
export function replaceProjectData(id: string, data: ProjectData, label: string): ProjectRecord | null {
  return transaction((db) => {
    const row = findRow(id)
    if (!row) return null
    insertSnapshot(id, label, row.data, false)
    db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(JSON.stringify(data), now(), id)
    return getProject(id)
  })
}

export function renameProject(id: string, name: string) {
  getDb().prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, id)
  return getProject(id)
}

export function deleteProject(id: string) {
  getDb().prepare('DELETE FROM projects WHERE id = ?').run(id)
}

export function duplicateProject(id: string): ProjectRecord | null {
  const source = getProject(id)
  return source ? createProject(`${source.name} (kópia)`, source.data) : null
}

export function listSnapshots(projectId: string): SnapshotSummary[] {
  const rows = getDb()
    .prepare('SELECT id, label, auto, created_at FROM snapshots WHERE project_id = ? ORDER BY id DESC')
    .all(projectId) as unknown as { id: number; label: string; auto: number; created_at: string }[]
  return rows.map((r) => ({ id: r.id, label: r.label, auto: r.auto === 1, createdAt: r.created_at }))
}

export function createSnapshot(projectId: string, label: string): SnapshotSummary | null {
  const row = findRow(projectId)
  if (!row) return null
  const id = insertSnapshot(projectId, label, row.data, false)
  return listSnapshots(projectId).find((s) => s.id === id) ?? null
}

export function restoreSnapshot(snapshotId: number): ProjectRecord | null {
  const snap = getDb().prepare('SELECT project_id, label, data FROM snapshots WHERE id = ?').get(snapshotId) as
    | { project_id: string; label: string; data: string }
    | undefined
  if (!snap) return null
  return replaceProjectData(snap.project_id, normalizeProjectData(JSON.parse(snap.data)), `Pred obnovením „${snap.label}“`)
}

export function deleteSnapshot(snapshotId: number) {
  getDb().prepare('DELETE FROM snapshots WHERE id = ?').run(snapshotId)
}
